class Solution {
  private int rows;
  private int cols;

  private void dfs(char[][] board, int i, int j) {
    if (i < 0 || i >= rows || j < 0 || j >= cols || board[i][j] != 'O') return;
    board[i][j] = '#';
    dfs(board, i + 1, j);
    dfs(board, i - 1, j);
    dfs(board, i, j + 1);
    dfs(board, i, j - 1);
  }

  public void solve(char[][] board) {
    if (board == null || board.length == 0) return;
    rows = board.length;
    cols = board[0].length;

    for (int i = 0; i < rows; i++) {
      dfs(board, i, 0);
      dfs(board, i, cols - 1);
    }
    for (int j = 0; j < cols; j++) {
      dfs(board, 0, j);
      dfs(board, rows - 1, j);
    }

    for (int i = 0; i < rows; i++) {
      for (int j = 0; j < cols; j++) {
        if (board[i][j] == 'O') {
          board[i][j] = 'X';
        } else if (board[i][j] == '#') {
          board[i][j] = 'O';
        }
      }
    }
  }
}

class Solution:
    def solve(self, board: List[List[str]]) -> None:
        if not board:
            return
        rows, cols = len(board), len(board[0])

        def dfs(i: int, j: int) -> None:
            if i < 0 or i >= rows or j < 0 or j >= cols or board[i][j] != "O":
                return
            board[i][j] = "#"
            dfs(i + 1, j)
            dfs(i - 1, j)
            dfs(i, j + 1)
            dfs(i, j - 1)

        for i in range(rows):
            dfs(i, 0)
            dfs(i, cols - 1)
        for j in range(cols):
            dfs(0, j)
            dfs(rows - 1, j)

        for i in range(rows):
            for j in range(cols):
                if board[i][j] == "O":
                    board[i][j] = "X"
                elif board[i][j] == "#":
                    board[i][j] = "O"

impl Solution {
  pub fn solve(board: &mut Vec<Vec<char>>) {
    if board.is_empty() {
      return;
    }
    let rows = board.len() as i32;
    let cols = board[0].len() as i32;

    fn dfs(board: &mut Vec<Vec<char>>, i: i32, j: i32, rows: i32, cols: i32) {
      if i < 0 || i >= rows || j < 0 || j >= cols || board[i as usize][j as usize] != 'O' {
        return;
      }
      board[i as usize][j as usize] = '#';
      dfs(board, i + 1, j, rows, cols);
      dfs(board, i - 1, j, rows, cols);
      dfs(board, i, j + 1, rows, cols);
      dfs(board, i, j - 1, rows, cols);
    }

    for i in 0..rows {
      dfs(board, i, 0, rows, cols);
      dfs(board, i, cols - 1, rows, cols);
    }
    for j in 0..cols {
      dfs(board, 0, j, rows, cols);
      dfs(board, rows - 1, j, rows, cols);
    }

    for i in 0..rows as usize {
      for j in 0..cols as usize {
        if board[i][j] == 'O' {
          board[i][j] = 'X';
        } else if board[i][j] == '#' {
          board[i][j] = 'O';
        }
      }
    }
  }
}

const solve = (board: string[][]): void => {
  if (board.length === 0) return;
  const rows = board.length;
  const cols = board[0].length;

  const dfs = (i: number, j: number): void => {
    if (i < 0 || i >= rows || j < 0 || j >= cols || board[i][j] !== 'O') return;
    board[i][j] = '#';
    dfs(i + 1, j);
    dfs(i - 1, j);
    dfs(i, j + 1);
    dfs(i, j - 1);
  };

  for (let i = 0; i < rows; i++) {
    dfs(i, 0);
    dfs(i, cols - 1);
  }
  for (let j = 0; j < cols; j++) {
    dfs(0, j);
    dfs(rows - 1, j);
  }

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      if (board[i][j] === 'O') board[i][j] = 'X';
      else if (board[i][j] === '#') board[i][j] = 'O';
    }
  }
};
